import{_ as t,o as s,c as a,aj as d}from"./framework.js";const u=JSON.parse('{"title":"项目资源与目录 | Cli / Project | Documentation","description":"项目资源与目录 in Kooboo: Kooboo CLI 根据本地文件所在目录识别站点资源。只有支持的资源目录和文件类型会参与拉取、推送和同步。","frontmatter":{"title":"项目资源与目录 | Cli / Project | Documentation","description":"项目资源与目录 in Kooboo: Kooboo CLI 根据本地文件所在目录识别站点资源。只有支持的资源目录和文件类型会参与拉取、推送和同步。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cli/project/resources.html"}]]},"headers":[],"relativePath":"zh/cli/project/resources.md","filePath":"cli/project/resources.md","lastUpdated":1784361314000}'),o={name:"zh/cli/project/resources.md"};function c(i,e,p,l,n,r){return s(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="项目资源与目录" tabindex="-1">项目资源与目录 <a class="header-anchor" href="#项目资源与目录" aria-label="Permalink to &quot;项目资源与目录&quot;">​</a></h1><p>Kooboo CLI 根据本地文件所在目录识别站点资源。只有支持的资源目录和文件类型会参与拉取、推送和同步。</p><h2 id="站点资源目录" tabindex="-1">站点资源目录 <a class="header-anchor" href="#站点资源目录" aria-label="Permalink to &quot;站点资源目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>本地目录</th><th>资源</th><th>支持的文件</th></tr></thead><tbody><tr><td><code>src/api</code></td><td>后端 API</td><td><code>.ts</code>、<code>.js</code></td></tr><tr><td><code>src/code</code></td><td>CodeBlock</td><td><code>.ts</code>、<code>.js</code></td></tr><tr><td><code>src/pagescript</code></td><td>PageScript</td><td><code>.ts</code>、<code>.js</code></td></tr><tr><td><code>src/page</code></td><td>Page</td><td><code>.html</code></td></tr><tr><td><code>src/layout</code></td><td>Layout</td><td><code>.html</code></td></tr><tr><td><code>src/view</code></td><td>View</td><td><code>.html</code></td></tr><tr><td><code>src/js</code></td><td>前端脚本</td><td><code>.js</code></td></tr><tr><td><code>src/css</code></td><td>前端样式</td><td><code>.css</code></td></tr><tr><td><code>src/job</code></td><td>定时任务</td><td><code>.ts</code></td></tr><tr><td><code>content-file</code></td><td>内容文件</td><td>不限制扩展名</td></tr><tr><td><code>images</code></td><td>媒体库文件</td><td>不限制扩展名</td></tr><tr><td><code>mcp-tools</code></td><td>MCP 工具</td><td>直接子级 <code>.ts</code> 文件</td></tr><tr><td><code>src/module/&lt;module-name&gt;</code></td><td>模块资源</td><td>取决于模块子目录</td></tr></tbody></table><p><code>content-file</code>、<code>images</code> 和 <code>mcp-tools</code> 位于项目根目录，其他站点资源位于 <code>src</code> 下。</p><h2 id="名称与路径" tabindex="-1">名称与路径 <a class="header-anchor" href="#名称与路径" aria-label="Permalink to &quot;名称与路径&quot;">​</a></h2><p>API、CodeBlock、PageScript、Page、Layout 和 View 的嵌套目录会转为点分名称。例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/code/services/user.ts       → services.user</span></span>
<span class="line"><span>src/view/common/header.html     → common.header</span></span>
<span class="line"><span>src/page/account/profile.html   → account.profile</span></span></code></pre></div><p>Job 保留斜杠层级：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/job/order/sync.ts           → order/sync</span></span></code></pre></div><p>Script 和 Style 的嵌套目录也会参与资源名称：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/js/app/index.js             → app.index.js</span></span>
<span class="line"><span>src/css/app/index.css           → app.index.css</span></span></code></pre></div><p>如果脚本或样式需要稳定的公开访问地址，应在文件顶部显式声明 URL：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// @k-url /assets/app.js</span></span></code></pre></div><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* @k-url /assets/app.css */</span></span></code></pre></div><p><code>src/js</code> 和 <code>src/css</code> 是本地资源分类目录，不应直接出现在页面引用的公开 URL 中。</p><h2 id="page-和-api-的访问路径" tabindex="-1">Page 和 API 的访问路径 <a class="header-anchor" href="#page-和-api-的访问路径" aria-label="Permalink to &quot;Page 和 API 的访问路径&quot;">​</a></h2><p>Page 和 API 文件需要声明访问 URL，否则推送或同步时不会按预期保存：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- @k-url /products --&gt;</span></span></code></pre></div><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// @k-url /api/products</span></span></code></pre></div><p>URL 声明属于资源配置，不等同于本地文件路径。修改文件位置时，确认资源名称和公开 URL 都仍符合预期。</p><h2 id="模块资源" tabindex="-1">模块资源 <a class="header-anchor" href="#模块资源" aria-label="Permalink to &quot;模块资源&quot;">​</a></h2><p>模块资源位于：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/module/&lt;module-name&gt;/</span></span></code></pre></div><p>常见子目录包括 <code>api</code>、<code>code</code>、<code>backend</code>、<code>view</code>、<code>js</code>、<code>css</code>、<code>root</code>、<code>img</code> 和 <code>file</code>。推送或同步模块前，优先使用模块或模块子目录作为目标范围，避免修改无关站点资源。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../workflows/pull.html">拉取远端资源</a></li><li><a href="./../workflows/push.html">推送本地资源</a></li><li><a href="./../workflows/sync.html">持续同步</a></li></ul>`,27)])])}const g=t(o,[["render",c]]);export{u as __pageData,g as default};
